const item = $json;
const prompt = `Kamu adalah script writer konten TikTok untuk affiliator Indonesia.
Buat script video TikTok berdasarkan brief berikut:

Judul: ${item.title}
Jenis Konten: ${item.content_type}
Hook: ${item.hook}
Caption: ${item.caption}
Produk: ${item.product_name}
Selling Points: ${(item.selling_points || []).join(', ')}

Output HANYA JSON (tanpa markdown):
{
  "hook_text": "teks hook 3-5 detik pertama yang langsung menarik",
  "problem": "narasi problem/pain point relatable (10-15 detik)",
  "solution": "narasi solusi dengan produk (15-20 detik)",
  "cta": "call-to-action kuat di akhir (5-10 detik)",
  "visual_direction": "panduan visual: angle kamera, props, setting, transisi",
  "audio_cue": "rekomendasi sound/musik TikTok trending sesuai mood"
}`;
return [{ json: { prompt, item } }];

const raw = $json.choices[0].message.content;
let script;
try {
  script = JSON.parse(raw.replace(/```json\n?|\n?```/g, '').trim());
} catch(e) {
  script = { hook_text: '', problem: '', solution: '', cta: '', visual_direction: '', audio_cue: '' };
}
const item = $('Build Script Prompt').item.json.item;
return [{ json: { script, item } }];

